let ideas=[],state=JSON.parse(localStorage.getItem("adhyeshaPlanner")||"{}"),filter="all";const REFRESH_MS=20*60*1000,$=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat("en-IN").format(Math.round(n));
async function load(){try{const r=await fetch(`suggestions.json?t=${Date.now()}`,{cache:"no-store"}),payload=await r.json();if(!r.ok||payload.error)throw new Error();const videos=(Array.isArray(payload)?payload:payload.videos||[]).sort((a,b)=>b.vph-a.vph).slice(0,7);ideas=videos.map((v,i)=>({id:v.id,topic:v.title,priority:i<3?"high":"medium",format:"Original video",reason:`Current YouTube signal: ${fmt(v.vph)} views/hour and ${v.momentum.toFixed(1)}× momentum.`,angle:`Study the hook and topic, then create an original Adhyesha Rhymes story, music and thumbnail.`}));render()}catch{if(!ideas.length)$("#planGrid").innerHTML='<article class="plan-card"><h2>Live ideas temporarily unavailable</h2><p>The planner will retry automatically.</p></article>'}}
function render(){const list=ideas.filter(i=>filter==="all"||(state[i.id]||"idea")===filter);$("#planGrid").innerHTML=list.map(i=>{const s=state[i.id]||"idea";return `<article class="plan-card ${s==="done"?"done":""}"><div class="plan-top"><span class="priority ${i.priority}">${i.priority.toUpperCase()} PRIORITY</span><span>${s==="done"?"✅ Done":s==="planned"?"📋 Planned":"💡 Idea"}</span></div><h2>${i.topic}</h2><p>${i.reason}</p><div class="angle"><b>Suggested angle</b>${i.angle}</div><div class="plan-meta"><span>${i.format}</span><span>Hindi kids</span></div><div class="plan-actions"><button data-copy="${i.id}">Copy idea</button><button class="${s==="done"?"complete":"primary"}" data-next="${i.id}">${s==="idea"?"Plan video":s==="planned"?"Mark done":"Reset"}</button></div></article>`}).join("");document.querySelectorAll("[data-next]").forEach(b=>b.onclick=()=>{const id=b.dataset.next,s=state[id]||"idea";state[id]=s==="idea"?"planned":s==="planned"?"done":"idea";save()});document.querySelectorAll("[data-copy]").forEach(b=>b.onclick=()=>{const i=ideas.find(x=>x.id===b.dataset.copy);navigator.clipboard.writeText(i.topic+" — "+i.angle);b.textContent="Copied ✓";setTimeout(()=>b.textContent="Copy idea",1200)});stats()}
function stats(){const planned=ideas.filter(i=>state[i.id]==="planned").length,done=ideas.filter(i=>state[i.id]==="done").length;$("#plannedCount").textContent=planned;$("#completedCount").textContent=done;$("#highCount").textContent=ideas.filter(i=>i.priority==="high"&&state[i.id]!=="done").length;$("#doneCount").textContent=`${done} / ${ideas.length} completed`;$("#doneBar").style.width=(ideas.length?done/ideas.length*100:0)+"%"}function save(){localStorage.setItem("adhyeshaPlanner",JSON.stringify(state));render()}document.querySelectorAll(".planner-filters button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".planner-filters button").forEach(x=>x.classList.remove("active"));b.classList.add("active");filter=b.dataset.filter;render()});const menu=$("#menuBtn"),side=$("#sidebar"),scrim=$("#scrim");menu.onclick=()=>{side.classList.toggle("open");scrim.classList.toggle("open")};scrim.onclick=()=>{side.classList.remove("open");scrim.classList.remove("open")};load();setInterval(load,REFRESH_MS);
